INSERT OR IGNORE INTO producten (slug, naam, data, zichtbaar, volgorde, bijgewerkt) VALUES ('rover-co-t-shirt', 'Rover & Co T-shirt', '{"naam": "Rover & Co T-shirt", "categorie": "T-shirt", "lint": "Bestseller", "prijs": 20.0, "fotos": [{"klein": "/assets/producten/rover-co-t-shirt/1-s.webp", "groot": "/assets/producten/rover-co-t-shirt/1.webp"}, {"klein": "/assets/producten/rover-co-t-shirt/2-s.webp", "groot": "/assets/producten/rover-co-t-shirt/2.webp"}, {"klein": "/assets/producten/rover-co-t-shirt/3-s.webp", "groot": "/assets/producten/rover-co-t-shirt/3.webp"}, {"klein": "/assets/producten/rover-co-t-shirt/4-s.webp", "groot": "/assets/producten/rover-co-t-shirt/4.webp"}, {"klein": "/assets/producten/rover-co-t-shirt/5-s.webp", "groot": "/assets/producten/rover-co-t-shirt/5.webp"}], "opties": [{"naam": "Maat", "verplicht": true, "waarden": [{"waarde": "XS", "meerprijs": 0.0, "standaard": false}, {"waarde": "S", "meerprijs": 0.0, "standaard": false}, {"waarde": "M", "meerprijs": 0.0, "standaard": false}, {"waarde": "L", "meerprijs": 0.0, "standaard": false}, {"waarde": "XL", "meerprijs": 0.0, "standaard": false}, {"waarde": "XXL", "meerprijs": 0.0, "standaard": false}]}], "omschrijving": "<p>Een comfortabele t-shirt met een ingetogen, karaktervolle uitstraling. Ontworpen voor buitenmensen, liefhebbers van avontuur en wie houdt van eenvoud met een verhaal.</p><p>Op de borst staat een subtiel Rover & Co-logo. Op de rug komt het logo groter terug, centraal geplaatst en over de volledige breedte.</p><p><strong>Met elke aankoop steun je onze vereniging en de goede doelen waar we achter staan.</strong></p>"}', 1, 0, '2026-11-27');
INSERT OR IGNORE INTO producten (slug, naam, data, zichtbaar, volgorde, bijgewerkt) VALUES ('built-for-the-wild-t-shirt', 'Built for the Wild T-shirt', '{"naam": "Built for the Wild T-shirt", "categorie": "T-shirt", "lint": "", "prijs": 25.0, "fotos": [{"klein": "/assets/producten/built-for-the-wild-t-shirt/1-s.webp", "groot": "/assets/producten/built-for-the-wild-t-shirt/1.webp"}, {"klein": "/assets/producten/built-for-the-wild-t-shirt/2-s.webp", "groot": "/assets/producten/built-for-the-wild-t-shirt/2.webp"}, {"klein": "/assets/producten/built-for-the-wild-t-shirt/3-s.webp", "groot": "/assets/producten/built-for-the-wild-t-shirt/3.webp"}, {"klein": "/assets/producten/built-for-the-wild-t-shirt/4-s.webp", "groot": "/assets/producten/built-for-the-wild-t-shirt/4.webp"}, {"klein": "/assets/producten/built-for-the-wild-t-shirt/5-s.webp", "groot": "/assets/producten/built-for-the-wild-t-shirt/5.webp"}], "opties": [{"naam": "Maat", "verplicht": true, "waarden": [{"waarde": "XS", "meerprijs": 0.0, "standaard": false}, {"waarde": "S", "meerprijs": 0.0, "standaard": false}, {"waarde": "M", "meerprijs": 0.0, "standaard": false}, {"waarde": "L", "meerprijs": 0.0, "standaard": false}, {"waarde": "XL", "meerprijs": 0.0, "standaard": false}, {"waarde": "XXL", "meerprijs": 0.0, "standaard": false}]}, {"naam": "Kleur", "verplicht": true, "waarden": [{"waarde": "Beige", "meerprijs": 0.0, "standaard": false}, {"waarde": "Army", "meerprijs": 0.0, "standaard": false}]}], "omschrijving": "Een robuust T-shirt voor wie zich het liefst buiten de gebaande paden bevindt. De <em>Built for the Wild</em> tee combineert een vintage geïnspireerde illustratie van een klassieke Land Rover met bergen, dennenbossen en stoere details. De donkergroene print op een zandkleurig shirt zorgt voor een tijdloze outdoor look met karakter. Ideaal voor roadtrips, kampvuren, greenlaning weekends of gewoon dagelijks gebruik.<p><strong>Met elke aankoop steun je onze vereniging en de goede doelen waar we achter staan.</strong></p>"}', 1, 10, '2026-11-27');
INSERT OR IGNORE INTO producten (slug, naam, data, zichtbaar, volgorde, bijgewerkt) VALUES ('life-is-better-in-low-range-t-shirt', 'Life Is Better In Low Range T-shirt', '{"naam": "Life Is Better In Low Range T-shirt", "categorie": "T-shirt", "lint": "", "prijs": 25.0, "fotos": [{"klein": "/assets/producten/life-is-better-in-low-range-t-shirt/1-s.webp", "groot": "/assets/producten/life-is-better-in-low-range-t-shirt/1.webp"}, {"klein": "/assets/producten/life-is-better-in-low-range-t-shirt/2-s.webp", "groot": "/assets/producten/life-is-better-in-low-range-t-shirt/2.webp"}, {"klein": "/assets/producten/life-is-better-in-low-range-t-shirt/3-s.webp", "groot": "/assets/producten/life-is-better-in-low-range-t-shirt/3.webp"}, {"klein": "/assets/producten/life-is-better-in-low-range-t-shirt/4-s.webp", "groot": "/assets/producten/life-is-better-in-low-range-t-shirt/4.webp"}], "opties": [{"naam": "Maat", "verplicht": true, "waarden": [{"waarde": "XS", "meerprijs": 0.0, "standaard": false}, {"waarde": "S", "meerprijs": 0.0, "standaard": false}, {"waarde": "M", "meerprijs": 0.0, "standaard": false}, {"waarde": "L", "meerprijs": 0.0, "standaard": false}, {"waarde": "XL", "meerprijs": 0.0, "standaard": false}, {"waarde": "XXL", "meerprijs": 0.0, "standaard": false}]}, {"naam": "Kleur", "verplicht": true, "waarden": [{"waarde": "Beige", "meerprijs": 0.0, "standaard": false}, {"waarde": "Army", "meerprijs": 0.0, "standaard": false}]}], "omschrijving": "<p>Een T-shirt voor wie zich het liefst thuis voelt op grindwegen, tussen dennenbossen en rond een kampvuur na een lange dag onderweg. De “Life Is Better In Low Range” print brengt meteen dat herkenbare gevoel van avontuur, eenvoud en buitenleven.</p><p>De vintage illustratie van de klassieke Land Rover geeft het shirt een tijdloze outdoor uitstraling, terwijl de zachte aardetinten perfect passen bij roadtrips, greenlaning weekends en rustige avonden op de camping. De print heeft een subtiele verweerde look die mooi aansluit bij het robuuste karakter van het ontwerp.</p><p>Beschikbaar in een warme army green en een zandkleurige beige uitvoering. Draagbaar tijdens avonturen in de natuur, op Land Rover meetings of gewoon als comfortabel everyday shirt met karakter.</p><p><strong>Met elke aankoop steun je onze vereniging en de goede doelen waar we achter staan.</strong></p>"}', 1, 20, '2026-11-27');
INSERT OR IGNORE INTO producten (slug, naam, data, zichtbaar, volgorde, bijgewerkt) VALUES ('emaille-mok', 'Rover & Co emaille mok', '{"naam": "Rover & Co emaille mok", "categorie": "Mok", "lint": "", "prijs": 15.0, "fotos": [{"klein": "/assets/producten/emaille-mok/1-s.webp", "groot": "/assets/producten/emaille-mok/1.webp"}, {"klein": "/assets/producten/emaille-mok/2-s.webp", "groot": "/assets/producten/emaille-mok/2.webp"}, {"klein": "/assets/producten/emaille-mok/3-s.webp", "groot": "/assets/producten/emaille-mok/3.webp"}], "opties": [], "omschrijving": "<p>Stevige emaille mok voor dagelijks gebruik, binnen of buiten. Licht van gewicht en makkelijk mee te nemen, ideaal voor onderweg of aan het kampvuur.</p><p>Gemaakt om tegen een stootje te kunnen en eenvoudig schoon te maken. Geschikt voor koffie, thee of eender wat je wil meenemen op pad.</p><p>Een praktische mok die je er snel bij neemt, thuis of ergens buiten.</p>"}', 1, 30, '2026-11-27');
INSERT OR IGNORE INTO activiteiten (slug, titel, datum, data, zichtbaar, volgorde, bijgewerkt) VALUES ('church-of-rover', 'Church of Rover', '2026-11-22', '{"titel": "Church of Rover", "datum": "2026-11-22", "datum_label": "Zo 22 nov", "datum_lang": "zondag 22 november 2026", "locatie": "Kerk van Oostham", "uren": "Vanaf 10:00", "kort": "Land Rover-meeting aan de kerk van Oostham, met bezoek aan de kerktoren, rondrit, winterbar en vuurkorven.", "kenmerken": ["Torenbezoek €5 p.p.", "Roadbook €15 per wagen", "Winterbar en hotdogs"], "foto": "leden-kerk-oostham", "foto_alt": "Grijze Land Rover 110 op het kerkplein van Oostham", "omschrijving_html": "<p>Kom langs voor een gezellige dag rond de kerk van Oostham, met Land Rovers, winterse sfeer en activiteiten voor iedereen.</p><p>Bezoek de historische <strong>kerktoren van Oostham</strong> en geniet nadien van een drankje. Een bezoek kost <strong>€5 per persoon</strong> en gebeurt in tijdsloten van 10 minuten. Kies bij je inschrijving het gewenste tijdslot.</p><p>Daarnaast kan je genieten van onze <strong>winterbar</strong>, <strong>hotdogs</strong> en <strong>vuurkorf</strong>.</p><p>Om <strong>14:30</strong> vindt de wijding plaats en aansluitend vertrekken we voor een gezamenlijke <strong>Land Rover-rondrit met roadbook</strong>.</p><h3>Praktisch</h3><ul><li>Bezoek kerktoren: €5 p.p.</li><li>Rondrit met roadbook: €15 per wagen</li><li>Winterbar, hotdogs en vuurkorf ter plaatse</li><li>Kerkbezoeken van 10:00 tot 12:00 en van 13:00 tot 14:30</li></ul>", "inschrijven_url": "https://roverandco.be/products/church-of-rover-22-11-2026", "inschrijven_label": "Inschrijven", "affiche": "affiche-church-of-rover", "foto_pos": "50% 70%", "banner_foto": "leden-kerk-oostham", "banner_pos": "50% 45%", "banner_groen": true}', 1, 0, '2026-11-27');
INSERT OR IGNORE INTO activiteiten (slug, titel, datum, data, zichtbaar, volgorde, bijgewerkt) VALUES ('rit-tea-on-the-tailgate-kerst', 'Rit naar Tea on the Tailgate Kerst', '2026-12-18', '{"titel": "Rit naar Tea on the Tailgate Kerst", "datum": "2026-12-18", "datum_label": "Vr 18 dec", "datum_lang": "vrijdag 18 december 2026", "locatie": "Vertrek aan The Wolfgarage, Ham", "uren": "Vertrek 18:00", "kort": "Samen in colonne van The Wolfgarage naar de kersteditie van Tea on the Tailgate in Lille. Gratis, wel even inschrijven.", "kenmerken": ["Gratis", "Vertrek 18:00 aan The Wolfgarage", "Tea on the Tailgate 19:00 tot 22:00"], "foto": "leden-kerst-oostham", "foto_alt": "Defender met kerstverlichting naast de kerstboom aan de kerk van Oostham", "omschrijving_html": "<p>Tea on the Tailgate houdt een kersteditie in Lille: een gezellige avondmeet voor Land Rover-rijders en liefhebbers. Wij rijden er samen in colonne naartoe.</p><h3>Praktisch</h3><ul><li><strong>Vertrek:</strong> 18:00 aan The Wolfgarage, Olmensesteenweg 105, 3945 Tessenderlo-Ham</li><li><strong>Bestemming:</strong> Tea on the Tailgate Kersteditie, Poeyelheide 13t, Lille</li><li><strong>Meet:</strong> 19:00 tot 22:00</li><li><strong>Prijs:</strong> gratis</li></ul><p>Schrijf je even in, zo weten we met hoeveel wagens we vertrekken.</p>", "inschrijven_url": "", "inschrijven_label": "", "inschrijving": {"open": true, "sluit": "2026-12-18", "wagen": true, "onderdelen": [{"id": "wagen", "naam": "Wagen in de colonne", "prijs": 0, "per": "wagen", "max": 3}, {"id": "personen", "naam": "Personen", "prijs": 0, "per": "persoon", "max": 10}]}, "foto_credit": "lid Rover & Co", "foto_pos": "50% 62%"}', 1, 10, '2026-11-27');
INSERT OR IGNORE INTO activiteiten (slug, titel, datum, data, zichtbaar, volgorde, bijgewerkt) VALUES ('wild-and-wheels', 'Wild & Wheels', '2027-05-28', '{"titel": "Wild & Wheels", "datum": "2027-05-28", "datum_label": "28–30 mei", "datum_lang": "vrijdag 28 tot zondag 30 mei 2027", "locatie": "Pakawi Park, Olmen", "uren": "Vr 18:00 tot zo 18:00", "kort": "Het Land Rover-weekend in Pakawi Park, opvolger van Wool & Wheels. Kamperen, offroad, roadbook en Sunday Drive.", "kenmerken": ["Pakawi Park", "28–30 mei 2027", "Kamperen vanaf vrijdag"], "foto": "standen", "foto_alt": "Rally-Defenders op het festivalterrein", "omschrijving_html": "<p>Wild &amp; Wheels is de opvolger van Wool &amp; Wheels: een weekend voor Land Rovers in Pakawi Park, van vrijdag 28 mei om 18:00 tot zondag 30 mei om 18:00.</p><p>Iedereen met een Land Rover is welkom, klassiek of modern, en ook verwante merken zoals Minerva en Santana. Een deel van de opbrengst gaat naar Pakawi Park.</p><h3>Stel je weekend samen</h3><ul><li><strong>Camping weekend</strong>: €70 per Land Rover, aankomst vanaf vrijdag 18:00</li><li><strong>Offroad-track weekend</strong>: €40 per Land Rover</li><li><strong>Roadbook zaterdag</strong>: €35 per Land Rover, beperkte plaatsen</li><li><strong>Sunday Drive</strong>: €25 per Land Rover, beperkte plaatsen</li><li><strong>Barbecue zaterdag</strong>: €25 per volwassene, €15 per kind (3 tot 11 jaar)</li></ul><p>Ontbijt en toegang tot het dierenpark volgen nog.</p>", "inschrijven_url": "", "inschrijven_label": "", "inschrijving": {"open": true, "sluit": "2027-05-28", "wagen": true, "onderdelen": [{"id": "camping", "naam": "Camping weekend", "prijs": 70, "per": "wagen", "max": 10, "melding_vanaf": 100, "uitleg": "Vrijdag 18:00 tot zondag 18:00"}, {"id": "track", "naam": "Offroad-track weekend", "prijs": 40, "per": "wagen", "max": 10, "melding_vanaf": 100}, {"id": "roadbook", "naam": "Roadbook zaterdag", "prijs": 35, "per": "wagen", "max": 10, "capaciteit": 50}, {"id": "sundaydrive", "naam": "Sunday Drive", "prijs": 25, "per": "wagen", "max": 10, "capaciteit": 50}, {"id": "bbq", "naam": "Barbecue zaterdag (volwassene)", "prijs": 25, "per": "persoon", "max": 20}, {"id": "bbq_veg", "naam": "Barbecue zaterdag vegetarisch (volwassene)", "prijs": 25, "per": "persoon", "max": 20}, {"id": "bbq_kind", "naam": "Barbecue zaterdag (kind 3 tot 11 jaar)", "prijs": 15, "per": "persoon", "max": 20}]}, "aftellen": {"start": "2027-05-28T18:00:00+02:00", "einde": "2027-05-30T18:00:00+02:00"}, "fotos": [["leden-daktenten-rij", "Defenders met daktenten op een kampeerterrein"], ["leden-zonsondergang", "Defender met daktent bij zonsondergang"], ["leden-track-rood", "Rode Defender 90 op een zandheuvel"], ["leden-vuur-hond", "Defender met daktent, vuurschaal en border collie"], ["leden-lightweight-110", "Gele Lightweight naast een zilveren Defender 110"], ["leden-daktent-rivier", "Defender met groene daktent aan de rivier"], ["ww-colonne-weg", "Colonne Land Rovers op een landweg"], ["ww-giraffen", "Twee giraffen in Pakawi Park"], ["ww-series-modder", "Land Rover Series door de modder"], ["ww-daktenten", "Defenders met daktenten op de camping"], ["ww-olifant", "Olifant in Pakawi Park"], ["ww-koppel-dak", "Koppel op het dak van hun Land Rover"], ["ww-modder-spat", "Defender spat door de modder"], ["ww-maki", "Ringstaartmaki''s in het gras"], ["ww-rij-landys", "Rij Defenders op het terrein"], ["ww-camping-bord", "Campingbord naast een groene Defender"], ["ww-kraanvogel", "Kroonkraanvogel in Pakawi Park"], ["ww-bar", "Bezoekers aan de bar op het festivalterrein"]], "fotos_titel": "Foto''s van leden, vorige editie en Pakawi Park"}', 1, 20, '2026-11-27');
